+/*
+// Ensure that exception handler preserves the verification state before the putfield
+value class HasStrictFieldSafe {
+   Integer sf;
+   HasStrictFieldSafe(Integer something) {
+      try {
+        this.sf = something;
+      }
+      catch (Throwable ex) {
+        this.sf = something;
+      }
+   }
+}
+*/
+
+final class HasStrictFieldSafe version 72:65535
+{
+  final strict Field sf:"Ljava/lang/Integer;";
+
+  Method       "<init>":"(Ljava/lang/Integer;)V"
+    stack 2  locals 3
+  {
+         aload_0;
+         aload_1;
+         try               T0;
+         putfield          Field sf:"Ljava/lang/Integer;";
+         endtry            T0;
+         goto              L12;
+         catch             T0 java/lang/Throwable;
+         stack_frame_type  early_larval;
+           unset_fields    sf:"Ljava/lang/Integer;";
+           frame_type      stack1;
+             stack_map     class java/lang/Throwable;
+         pop;
+         aload_0;
+         aload_1;
+         putfield          Field sf:"Ljava/lang/Integer;";
+  L12:   stack_frame_type early_larval;
+           unset_fields;
+           frame_type  same;
+         aload_0;
+         invokespecial     Method java/lang/Object."<init>":"()V";
+         return;
+  }
+
+  LoadableDescriptors      "Ljava/lang/Integer;";
+}
